__NUXT_JSONP__("/svet/stat/sudan/vyrobky", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{tabsLoad:{tabWhatToSee:d,tabPrice:d,tabPeople:d,tabTrip:d,tabContact:d,tabHotel:d,tabNeighboring:9,tabVideos:e,tabArticles:e,tabWallSockets:h,tabChains:1,tabFauna:e,tabFlora:e,tabFoods:e,tabBrands:e},place:[{tld:".sd",name:"Súdán",area:1861484,population:44754597,slug:i,id_continent:f,information_chatgpt:"\u003Cp\u003ESúdán je rozlehlý stát v severovýchodní Africe, který hraničí s Egyptem na severu, Eritreou a Etiopií na východě, Jižním Súdánem na jihu a Čadem a Libyí na západě. Súdán má mnoho kulturových bohatství a historických památek, jako jsou například pyramidy v Meroe. \u003C\u002Fp\u003E\n\u003Cp\u003ESúdán je domovem mnoha etnických skupin a kultur, včetně kmene Núbie, kteří jsou známí pro svou rozmanitou řemeslnou výrobu a historii v oblasti. Kromě toho můžete navštívit i města Khartúm a Omdurman, která jsou domovem mnoha muzeí a galerií, které ukazují bohatství historie a kultury Súdánu. \u003C\u002Fp\u003E\n\u003Cp\u003EPříroda v Súdánu je velmi pestrá, od pouští po savany a bažiny. Je zde také řada národních parků, jako například Dinder National Park nebo Jebel Barkal, které poskytují příležitosti k pozorování zvířat v přirozeném prostředí. \u003C\u002Fp\u003E\n\u003Cp\u003EPřestože Súdán nemusí být nejčastějším turistickým cílem, nabízí mnoho možností pro dobrodružství a objevování. Pamatujte však, že bezpečnostní situace v Súdánu může být nestabilní a cestování sem by mělo být pečlivě zváženo a připraveno. \u003C\u002Fp\u003E",money_prices:[{name:"Taxi (cena za km)",value:15,date_update:a},{name:"Hlavní jídlo",value:j,date_update:a},{name:"Chleba",value:k,date_update:a},{name:"Mléko",value:b,date_update:a},{name:"Voda (500ml)",value:b,date_update:a},{name:"Espresso",value:3.5,date_update:a},{name:"Zmrzlina (jeden kopeček)",value:b,date_update:a},{name:"Pivo",value:25,date_update:a},{name:"Krabička cigaret",value:b,date_update:a},{name:"Bic Mac",value:b,date_update:a},{name:"Coca Cola (500ml)",value:j,date_update:a}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:l,date_update:a},{name:"Policie",value:"911",date_update:a},{name:"Hasiči",value:"998",date_update:a},{name:"Zdravotnická záchranná služba",value:l,date_update:a}],phone_prefix:"+249",coordinates:[{latitude:"12.8628",longitude:"30.2176"}],people_religion:[{name:"Sunitský islám",value:"97%",date_update:c},{name:"Křesťanství",value:"2%",date_update:c},{name:"Tradiční náboženství",value:"1%",date_update:c},{name:"Nevěřící",value:"0.1%",date_update:c}],people_nationality:[{name:"Arabové",value:"70%",date_update:c},{name:"Núbijci",value:"13%",date_update:c},{name:"Fulaové",value:"7%",date_update:c},{name:"Bez příslušnosti k etnické skupině",value:"10%",date_update:c}],visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Súdánu je třeba mít platný cestovní doklad, tedy pas. Občanský průkaz není dostatečný.",date_update:a},{name:"Cestovní pas",value:"Pro vstup do Súdánu je nutné mít platný cestovní pas s minimální platností 6 měsíců od data příjezdu.",date_update:a},{name:"Vízum",value:"Pro vstup do Súdánu je třeba mít vízum. Pro občany České republiky a některé další země existuje možnost získání víza po příletu na letišti. Nicméně doporučuje se získání víza před cestou na příslušné ambasádě. Prodloužení víza na místě je velmi obtížné.",date_update:a},{name:"Očkování",value:"Pro vstup do Súdánu nejsou povinná žádná očkování. Nicméně doporučuje se očkování proti žluté zimnici a hepatitidě A a B. Před cestou je vhodné konzultovat očkování s lékařem.",date_update:a},{name:"Cestovní pojištění",value:"Cestovní pojištění není povinné pro vstup do Súdánu, ale doporučuje se ho mít. Pokud potřebujete lékařskou péči na místě, mohou být náklady vysoké.",date_update:a},{name:"Bezpečností situace",value:"V Súdánu dochází k násilným střetům mezi různými skupinami, a to i v hlavním městě Chartúmu. Turisté by měli být opatrní a vyhýbat se oblastem, kde dochází k násilí. Doporučuje se sledovat aktuální bezpečnostní situaci a mít plán evakuace v případě nutnosti.",date_update:a},{name:"Další informace",value:"V Súdánu je třeba respektovat místní zvyklosti a kulturu. Doporučuje se nosit zahalující oblečení, zejména při návštěvě městských částí obývaných muslimským obyvatelstvem. Je vhodné předem se informovat o místních zvycích a tradicích. Při focení lidí nebo místních obyvatelstva je nutné mít jejich souhlas.",date_update:a}],type_place:m,id_image_cover:g,id_image_hero:g,id_city_main:1921,affiliate:[{name:"booking",value:d}],mpz:"SD",alerts:b,zoom:[{google:k,booking:f}],ids_neighboring_countries:[{id:40},{id:41},{id:65},{id:67},{id:69},{id:115},{id:136},{id:215},{id:231}],organization:b,apps:b,links:b,information_author:b,seo_tags:b,language_phrases:b,wall_sockets:b,id:196,facts_place:b,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2024-02-10T00:28:20.01422+00:00",name_original:b,currency:[{code:"SDG",name:"Súdánská libra"}]}],imagePlace:[{id:g,name:i,source:"\u002Fworld\u002Fstates\u002F",type:m,author:"pixabay.com",created_at:"2023-05-03T20:14:00.749527+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:f,slug:"afrika",name:"Afrika",area:30370000,population:1340000000,population_density:44.12,number_states:54,information_chatgpt:"\u003Cp\u003EAfrika je největší kontinent na Zemi a rozkládá se na ploše přesahující 30 milionů kilometrů čtverečních. Nachází se zde více než 50 zemí a žije zde více než 1,3 miliardy lidí. \u003C\u002Fp\u003E\n\u003Cp\u003EJižní Afrika, Egypt, Maroko a Keňa patří mezi nejoblíbenější turistické cíle v Africe. V Jihoafrické republice se můžete podívat na slavné Krugerův národní park a sledovat zde život zvířat v jejich přirozeném prostředí. Egypt je zase proslulý svými pyramidami, které se nacházejí v Gíze. V Maroku můžete navštívit tradiční trhy, zatímco v Keni se můžete setkat s Masajským kmenem a podívat se na úžasnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má bohatou historii a kulturu. První lidé, kteří se usadili v Africe, byli loveckým a sběračským národem. Poté se v této oblasti objevily první civilizace, jako je Kúšská říše, Egyptská říše nebo Království Aksum. Afrika byla také kolonizována evropskými mocnostmi a toto období mělo značný dopad na dnešní politickou situaci na kontinentu.\u003C\u002Fp\u003E\n\u003Cp\u003EJe důležité zmínit, že Afrika má velké množství jazyků a kultur. Zahrnuje mnoho různých národů a etnických skupin, a to má vliv na různorodost obyvatelstva a kultury. Nejrozšířenějším jazykem je arabština, která se mluví především v severní Africe a v některých částech západní Afriky. Dalšími důležitými jazyky jsou svahilština, francouzština, portugalština, angličtina a mnoho dalších.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má také nádhernou přírodu. Nachází se zde nejvyšší hora světa, Kilimandžáro, která se nachází na území Tanzanie a Keňy. Kromě toho se v Africe nachází také největší pouště na světě, Sahara, a největší prales, Kongský prales. Na tomto kontinentě můžete vidět také mnoho zvířat, jako jsou sloni, lvi, gepardi, zebry a mnoho dalších druhů. V Africe se také nachází několik nejvýznamnějších řek světa, jako je Nil, Kongo, Niger a Zambezi.\u003C\u002Fp\u003E\u003Cp\u003EAfrika je bohužel také známá pro své problémy. Mnoho zemí se potýká s chudobou, nedostatkem potravin a vody, nemocemi a válečnými konflikty. Mnoho afrických zemí závisí na zemědělství a rybolovu, což však často není dostatečně výnosné, aby zabezpečilo potřeby obyvatelstva. Kromě toho jsou některé země v Africe trvale postižené extrémními přírodními katastrofami, jako jsou sucha, povodně a bouře.\u003C\u002Fp\u003E\n\u003Cp\u003ENa druhou stranu se v Africe také nachází mnoho lidí, kteří se snaží změnit situaci a zlepšit životy svých spoluobčanů. Vznikají neziskové organizace, které se snaží pomáhat při řešení těchto problémů a zlepšovat kvalitu života v mnoha afrických zemích. Zároveň se v posledních letech objevují nové možnosti pro ekonomický růst a rozvoj, jako jsou technologické start-upy a zahraniční investice.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika je fascinující kontinent, který nabízí mnoho zážitků a zároveň v sobě ukrývá mnoho výzev. Pokud se rozhodnete navštívit Afriku, můžete se těšit na krásnou přírodu, bohatou kulturu a nezapomenutelné zážitky. Je však také důležité být obezřetný a připravený na místní podmínky, protože některé oblasti mohou být nebezpečné kvůli konfliktům nebo zločinnosti.\u003C\u002Fp\u003E",coordinates:[{latitude:1.650801,longitude:17.371642}],type_place:"continent",id_image_cover:f,id_image_hero:f,zoom:[{google:h,booking:3}],information_author:b,seo_tags:b,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:b}]}],fetch:{},mutations:[]}}("05-2023",null,"04-2023",true,0,5,367,2,"sudan",10,4,"999","state")));